{
  "type": "function",
  "name": "schedule_freight_pickup",
  "description": "Schedules a freight pickup using the supplied UTC pickup time, declared currency, shipment weight, and depot coordinates. Use this tool when a freight pickup needs to be scheduled; do not use it to obtain rates or track an existing shipment. The coordinate string must use the exact format lat,lon with no space after the comma. The carrier note is optional and may be null; scheduling constraints and availability are determined by the receiving service.",
  "strict": true,
  "parameters": {
    "type": "object",
    "properties": {
      "pickup_iso_utc": {
        "type": "string",
        "description": "Pickup date and time as an ISO 8601 timestamp in UTC, with a trailing Z (for example, 2026-04-20T14:30:00Z)."
      },
      "declared_currency": {
        "type": "string",
        "description": "Three-letter ISO 4217 currency code in uppercase (for example, USD or EUR)."
      },
      "weight_kg": {
        "type": "number",
        "description": "Shipment weight in kilograms; must be greater than zero."
      },
      "depot_coordinates": {
        "type": "string",
        "description": "Depot coordinates as latitude,longitude in decimal degrees, with no space after the comma (for example, 37.7749,-122.4194)."
      },
      "carrier_note": {
        "type": ["string", "null"],
        "description": "Optional note for the carrier. Provide a string or null if no note is supplied."
      }
    },
    "required": [
      "pickup_iso_utc",
      "declared_currency",
      "weight_kg",
      "depot_coordinates",
      "carrier_note"
    ],
    "additionalProperties": false
  }
}

{
  "type": "function",
  "name": "issue_prorated_credit",
  "description": "Issues a prorated account credit for an eligible billing period. Use this tool only after calculating the exact credit in integer cents and the billing days remaining from the user-provided billing dates; submit those calculated values, not dates or an estimate. Do not use this tool to calculate a proration, determine eligibility, or issue a full-period refund. The caller must establish the applicable proration policy and validate the dates before invoking this tool. Amounts are integer cents, and billing days remaining is an integer count under that policy.",
  "strict": true,
  "parameters": {
    "type": "object",
    "properties": {
      "rationale": {
        "type": "string",
        "description": "Concise calculation summary showing the billing-period day count, days remaining, and proration used to derive credit_cents. Include no unsupported assumptions; this field is required so a non-reasoning model can provide its calculation basis before submission."
      },
      "credit_cents": {
        "type": "integer",
        "description": "Exact prorated credit to issue, in integer cents. Calculate from the applicable policy and user billing dates before calling; do not round to dollars or provide a decimal amount. Must be non-negative."
      },
      "billing_days_remaining": {
        "type": "integer",
        "description": "Number of billing-period days remaining, calculated from the user-provided billing dates using the applicable policy's inclusive or exclusive date convention. Must be non-negative."
      }
    },
    "required": [
      "rationale",
      "credit_cents",
      "billing_days_remaining"
    ],
    "additionalProperties": false
  }
}

