        "description": "Exact count of billable days remaining in the current billing period, calculated from the user's billing dates using the applicable inclusive/exclusive boundary convention. Submit a whole-number day count, not a date or estimate."
      },
      "billing_period_start": {
        "type": "string",
        "format": "date",
        "description": "Start date of the billing period, in ISO 8601 YYYY-MM-DD format."
      },
      "billing_period_end": {
        "type": "string",
        "format": "date",
        "description": "End date of the billing period, in ISO 8601 YYYY-MM-DD format."
      },
