{
  "type": "function",
  "name": "issue_prorated_credit",
  "description": "Issue a prorated billing credit. Before calling, calculate every derived value from the supplied billing dates and amount; do not guess or delegate the calculation. Dates are ISO 8601 calendar dates (YYYY-MM-DD). The billing period is start-inclusive and end-exclusive. Total billing days = (period_end_date − period_start_date) in calendar days; it must be positive. Remaining billing days = (period_end_date − max(effective_date, period_start_date)) in calendar days, clamped to [0, total billing days]. Thus, an effective date on the period end or later yields zero days; an effective date on or before the start yields the full period. Compute credit_cents by rounding amount_cents × remaining_billing_days ÷ total_billing_days to the nearest integer cent, with exact halves rounded up. Use integer arithmetic: (amount_cents × remaining_billing_days × 2 + total_billing_days) // (2 × total_billing_days). Do not call if required dates or amount are missing, invalid, or ambiguous.",
  "parameters": {
    "type": "object",
    "properties": {
      "amount_cents": {
        "type": "integer",
        "minimum": 0,
        "description": "Original amount paid for the entire billing period, in integer cents."
      },
      "period_start_date": {
        "type": "string",
        "format": "date",
        "description": "Inclusive start date of the billing period, YYYY-MM-DD."
      },
      "period_end_date": {
        "type": "string",
        "format": "date",
        "description": "Exclusive end date of the billing period, YYYY-MM-DD; must be later than period_start_date."
      },
      "effective_date": {
        "type": "string",
        "format": "date",
        "description": "Date the credit takes effect, YYYY-MM-DD."
      },
      "total_billing_days": {
        "type": "integer",
        "minimum": 1,
        "description": "Calculated calendar-day difference between period_end_date and period_start_date."
      },
      "remaining_billing_days": {
        "type": "integer",
        "minimum": 0,
        "description": "Calculated remaining calendar days using the rules in the tool description; must not exceed total_billing_days."
      },
      "credit_cents": {
        "type": "integer",
        "minimum": 0,
        "description": "Calculated prorated credit in integer cents, rounded to nearest cent with half-cent ties rounded up."
      }
    },
    "required": [
      "amount_cents",
      "period_start_date",
      "period_end_date",
      "effective_date",
      "total_billing_days",
      "remaining_billing_days",
      "credit_cents"
    ],
    "additionalProperties": false
  },
  "strict": true
}

